typedef struct { int n; } Seed;                       /* coalgebra state      */
static Seed shrink(Seed s) { s.n -= 1; return s; }   /* unfold one step      */
static int  done(Seed s)   { return s.n == 0; }      /* termination          */
static long step(long acc, Seed s) { return acc * s.n; }  /* algebra        */

long factorial(int n) {                              /* fused: one pass      */
    long acc = 1;
    Seed s; s.n = n;
    while (!done(s)) {                               /* nothing is stored    */
        acc = step(acc, s);                          /* fold this layer now  */
        s = shrink(s);                               /* next seed            */
    }
    return acc;
}
